"""Merge user records from three sources with source-priority conflict resolution.

Priority: source_a > source_b > source_c
"""
from __future__ import annotations

import json
from typing import Any

import pandas as pd

# ---------------------------------------------------------------------------
# Source configuration: how to read each file and rename its columns to the
# unified schema. Only the mappings required by the task are applied.
# ---------------------------------------------------------------------------
SOURCES = [
    (
        "source_a",
        "/data/source_a/users.json",
        "json",
        {
            "id": "user_id",
            "full_name": "name",
            "email": "email",
            "registration_date": "created_date",
            "status": "status",
        },
    ),
    (
        "source_b",
        "/data/source_b/users.csv",
        "csv",
        {
            "user_id": "user_id",
            "name": "name",
            "email_address": "email",
            "created_at": "created_date",
            # is_active is not one of the specified mappings -> ignored
        },
    ),
    (
        "source_c",
        "/data/source_c/users.parquet",
        "parquet",
        {
            "userId": "user_id",
            "userName": "name",
            "email": "email",
            "joined": "created_date",
            # active is not one of the specified mappings -> ignored
        },
    ),
]

FIELDS = ["name", "email", "created_date", "status"]
OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def read_source(source: str, path: str, kind: str) -> pd.DataFrame:
    if kind == "json":
        df = pd.read_json(path)
    elif kind == "csv":
        df = pd.read_csv(path)
    elif kind == "parquet":
        df = pd.read_parquet(path)
    else:  # pragma: no cover - defensive
        raise ValueError(f"Unsupported source kind: {kind}")
    return df


def clean_text(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    text = str(value).strip()
    return text if text != "" else None


def normalize_date(value: Any) -> str | None:
    """Return the date as YYYY-MM-DD, or None if it cannot be parsed."""
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    text = str(value).strip()
    if text == "":
        return None
    parsed = pd.to_datetime(text, errors="coerce")
    if pd.isna(parsed):
        return text
    return parsed.strftime("%Y-%m-%d")


def normalize_user_id(value: Any) -> int | None:
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        parsed = pd.to_numeric(value, errors="coerce")
        return None if pd.isna(parsed) else int(parsed)


def load_normalized() -> dict[str, dict[int, dict[str, Any]]]:
    """Read all sources into {source_name: {user_id: {field: value}}}.

    Only non-null values are stored, so a missing/blank field never masks a
    lower-priority source's value.
    """
    normalized: dict[str, dict[int, dict[str, Any]]] = {}

    for source, path, kind, rename in SOURCES:
        df = read_source(source, path, kind)
        df = df.rename(columns=rename)

        # Keep the unified columns this source actually provides.
        keep = [c for c in OUTPUT_COLUMNS if c in df.columns]
        df = df[keep]

        records: dict[int, dict[str, Any]] = {}
        for row in df.to_dict(orient="records"):
            user_id = normalize_user_id(row.get("user_id"))
            if user_id is None:
                continue

            rec: dict[str, Any] = {}
            name = clean_text(row.get("name"))
            email = clean_text(row.get("email"))
            created_date = normalize_date(row.get("created_date"))
            status = clean_text(row.get("status"))

            if name is not None:
                rec["name"] = name
            if email is not None:
                rec["email"] = email
            if created_date is not None:
                rec["created_date"] = created_date
            if status is not None:
                rec["status"] = status

            # If a user_id repeats within one source, the first occurrence wins.
            records.setdefault(user_id, rec)

        normalized[source] = records

    return normalized


def merge(normalized: dict[str, dict[int, dict[str, Any]]]) -> tuple[pd.DataFrame, list[dict[str, Any]]]:
    priority = [name for name, *_ in SOURCES]

    all_ids = sorted({uid for records in normalized.values() for uid in records})

    merged_rows = []
    conflicts: list[dict[str, Any]] = []

    for user_id in all_ids:
        merged_row: dict[str, Any] = {"user_id": int(user_id)}

        for field in FIELDS:
            values = {
                source: normalized[source][user_id][field]
                for source in priority
                if user_id in normalized[source] and field in normalized[source][user_id]
            }

            if values:
                # Highest-priority source that actually provides a value wins.
                selected = next(values[source] for source in priority if source in values)
            else:
                selected = None

            merged_row[field] = selected

            # A field is a conflict only when sources supply differing values.
            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": int(user_id),
                        "field": field,
                        "values": values,
                        "selected": selected,
                    }
                )

        merged_rows.append(merged_row)

    df = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)

    # Enforce output dtypes.
    df["user_id"] = df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        df[col] = df[col].astype("string")

    return df, conflicts


def main() -> None:
    normalized = load_normalized()
    df, conflicts = merge(normalized)

    df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    print(df.to_string(index=False))
    print("\nDtypes:")
    print(df.dtypes)
    print(f"\nTotal users: {len(df)}")
    print(f"Total conflicts: {len(conflicts)}")
    for c in conflicts:
        print(f"  user {c['user_id']} field {c['field']}: {c['values']} -> {c['selected']}")


if __name__ == "__main__":
    main()
PYEOF
echo "--- script written ---"
